function g(n){if(n==null)return"";if(typeof n=="string")return n.trim().replace(/,/g,"");if(typeof n=="number"){if(!Number.isFinite(n))return"";const t=n.toString();return!t.includes("e")&&!t.includes("E")?t:n.toFixed(20).replace(/\.?0+$/,"")||"0"}return typeof n=="bigint"?n.toString():String(n).trim().replace(/,/g,"")}function c(n){const t=g(n);return!t||!/^\d+(\.\d+)?([eE][+-]?\d+)?$/.test(t)?null:t}const l=c;function m(n){return n==null||n===""?"—":String(n).trim().replace(/,/g,"")||"—"}const h=m;function S(n){const t=c(n);if(t==null)throw new Error("单价无效");return t}function w(n){const t=l(n);if(t==null)throw new Error("数量无效");return t}function a(n){const t=n.split(".");return t.length>1?t[1].length:0}function f(n,t){const[e,r=""]=n.split(".");return`${e}.${r.padEnd(t,"0")}`}function u(n){const t=n.trim().replace(/,/g,""),[e,r=""]=t.split(".");if(!/^\d+$/.test(e)||r&&!/^\d+$/.test(r))throw new Error("数值无效");return BigInt(`${e}${r}`)}function y(n,t){const e=c(n),r=c(t);if(e==null||r==null)return!1;if(e===r)return!0;try{const i=Math.max(a(e),a(r)),o=u(f(e,i)),s=u(f(r,i));return o===s}catch{return!1}}function b(n,t){const e=l(n),r=c(t);if(e==null||r==null)return 0;try{const i=a(e)+a(r),o=u(e)*u(r);if(i<=2){const p=o*10n**BigInt(2-i);return Number(p)}const s=10n**BigInt(i-2),d=s/2n;return Number((o+d)/s)}catch{return 0}}function P(n,t){return b(n,t)/100}export{y as a,h as b,P as c,w as d,l as e,m as f,S as n,c as p};
